#include "cli.hpp"
#include <iostream>
namespace exotic::autonomy::agents {
int run_agent_cli(AgentRepository&r,AgentRegistry&registry,AgentRecoveryManager&recovery,std::span<const std::string> args,std::ostream&out,std::ostream&err){if(args.empty()||args[0]=="status"){auto s=r.status(Clock::now()-std::chrono::seconds(30));out<<"EXOTIC AGENT RUNTIME 0.6\n"<<"registered="<<s.registered<<"\nactive="<<s.active<<"\navailable="<<s.available<<"\nunhealthy="<<s.unhealthy<<"\nrevoked="<<s.revoked<<"\nrunning_assignments="<<s.running_assignments<<"\nstale_bindings="<<s.stale_bindings<<'\n';return 0;}if(args[0]=="list"){for(const auto&a:r.load_agents())out<<a.id<<' '<<a.identity_key<<' '<<to_string(a.status)<<' '<<to_string(a.health)<<" workload="<<a.workload.active_tasks<<'/'<<a.workload.maximum_tasks<<'\n';return 0;}if(args[0]=="assignments"){for(const auto&a:r.load_active_assignments())out<<a.id<<" job="<<a.job_id<<" v="<<a.version<<" status="<<to_string(a.status)<<" agents="<<a.plan.agent_ids.size()<<'\n';return 0;}if(args[0]=="recover"){auto x=recovery.recover();out<<"stale_agents="<<x.stale_agents<<" released_bindings="<<x.released_bindings<<" interrupted_assignments="<<x.interrupted_assignments<<" replacements="<<x.replacements_created<<'\n';return 0;}if(args[0]=="revoke"&&args.size()>=3){auto id=static_cast<AgentId>(std::stoull(args[1]));return registry.revoke(id,args[2])?0:2;}err<<"usage: exotic agents [status|list|assignments|recover|revoke <id> <reason>]\n";return 2;}
}
